if __name__ == "__main__":
    import json, sys
    items = [l for l in open(sys.argv[1]).read().split("\n") if l and l != "ACTUALIZACION"]
    faltan = [i for i in items if i.strip() not in N]
    print("faltan", faltan)
    filas = [["Nombre en Resto Soft", "Cómo sale en el mensaje", "Revisar"]]
    for k, v in N.items():
        filas.append([k, v.rstrip("?"), "SÍ" if v.endswith("?") else ""])
    json.dump(filas, open(sys.argv[2], "w"), ensure_ascii=False)
    print(len(filas) - 1, "nombres,", sum(1 for f in filas if f[2]), "para revisar")
